import { isPlatformServer } from '@angular/common';
import { booleanAttribute, ChangeDetectionStrategy, Component, computed, effect, inject, input, model, NgModule, output, signal, ViewEncapsulation } from '@angular/core';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind, BindModule } from 'primeng/bind';
import { SharedModule } from 'primeng/api';
import type { GalleryActiveIndexChangeEvent, GalleryPassThrough, GalleryPendingAction } from 'primeng/types/gallery';
import { GalleryStyle } from './style/gallerystyle';
import { GalleryItem } from './gallery-item';
import { GalleryHeader } from './gallery-header';
import { GalleryContent } from './gallery-content';
import { GalleryFooter } from './gallery-footer';
import { GalleryBackdrop } from './gallery-backdrop';
import { GalleryToolbar } from './gallery-toolbar';
import { GalleryToolbarItem } from './gallery-toolbar-item';
import { GalleryPrev } from './gallery-prev';
import { GalleryNext } from './gallery-next';
import { GalleryZoomIn } from './gallery-zoom-in';
import { GalleryZoomOut } from './gallery-zoom-out';
import { GalleryZoomToggle } from './gallery-zoom-toggle';
import { GalleryRotateLeft } from './gallery-rotate-left';
import { GalleryRotateRight } from './gallery-rotate-right';
import { GalleryFlipX } from './gallery-flip-x';
import { GalleryFlipY } from './gallery-flip-y';
import { GalleryFullScreen } from './gallery-full-screen';
import { GalleryDownload } from './gallery-download';
import { GalleryThumbnail } from './gallery-thumbnail';
import { GalleryThumbnailContent } from './gallery-thumbnail-content';
import { GalleryThumbnailItem } from './gallery-thumbnail-item';

/**
 * Gallery is the main container component for the Gallery.
 * @group Components
 */
@Component({
    selector: 'p-gallery',
    standalone: true,
    imports: [BindModule],
    template: `<ng-content></ng-content>`,
    providers: [GalleryStyle, { provide: PARENT_INSTANCE, useExisting: Gallery }],
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    host: {
        '[class]': "cx('root')",
        tabindex: '0',
        '[attr.data-scope]': "'gallery'",
        '[attr.data-part]': "'root'",
        '[attr.data-fullscreen]': 'dataFullscreen()',
        '[attr.data-zoomed]': 'dataZoomed()',
        '[attr.data-rotated]': 'dataRotated()',
        '[attr.data-flipped]': 'dataFlipped()',
        '(keydown)': 'handleKeyDown($event)'
    },
    hostDirectives: [Bind]
})
export class Gallery extends BaseComponent<GalleryPassThrough> {
    componentName = 'Gallery';

    bindDirectiveInstance = inject(Bind, { self: true });

    /**
     * The index of the active item.
     * @group Props
     * @defaultValue 0
     */
    activeIndex = model<number>(0);

    /**
     * When defined, puts the fullscreen state in controlled mode; the value drives whether the gallery is fullscreen and changes are reported via onFullscreenChange instead of being handled internally.
     * @group Props
     */
    fullscreen = input<boolean | undefined, boolean | string | undefined>(undefined, { transform: (value) => (value === undefined ? undefined : booleanAttribute(value)) });

    /**
     * Whether pressing the Escape key exits fullscreen mode.
     * @defaultValue true
     * @group Props
     */
    closeOnEscape = input(true, { transform: booleanAttribute });

    /**
     * Callback fired when the gallery's active index changes.
     * @param {GalleryActiveIndexChangeEvent} event - Custom active index change event.
     * @group Emits
     */
    onActiveIndexChange = output<GalleryActiveIndexChangeEvent>();

    /**
     * Callback fired when the fullscreen state should change (controlled mode).
     * @param {boolean} value - The next fullscreen state.
     * @group Emits
     */
    onFullscreenChange = output<boolean>();

    /**
     * Callback fired when the active item's zoom scale changes.
     * @param {number} scale - The current zoom scale.
     * @group Emits
     */
    onZoomChange = output<number>();

    /**
     * Callback fired when the active item's rotation changes.
     * @param {number} rotation - The current rotation in degrees.
     * @group Emits
     */
    onRotateChange = output<number>();

    /**
     * Callback fired when the active item's flip state changes.
     * @param {{ x: number; y: number }} flip - The current flip state.
     * @group Emits
     */
    onFlipChange = output<{ x: number; y: number }>();

    _componentStyle = inject(GalleryStyle);

    private isFullscreenInternal = signal(false);

    private fullscreenResizeTimer: ReturnType<typeof setTimeout> | null = null;

    private destroyed = false;

    isFullscreen = computed(() => this.fullscreen() ?? this.isFullscreenInternal());

    activeItemTransform = signal({ zoomed: false, rotated: false, flipped: false });

    pendingAction = signal<GalleryPendingAction | null>(null);

    itemCounter = 0;

    contentEl = signal<HTMLElement | null>(null);

    dataFullscreen = computed(() => (this.isFullscreen() ? '' : null));

    dataZoomed = computed(() => (this.activeItemTransform().zoomed ? '' : null));

    dataRotated = computed(() => (this.activeItemTransform().rotated ? '' : null));

    dataFlipped = computed(() => (this.activeItemTransform().flipped ? '' : null));

    private onNativeFullscreenChange = () => {
        const active = this.document?.fullscreenElement === this.$el;

        this.isFullscreenInternal.set(active);

        if (this.fullscreen() !== undefined && this.fullscreen() !== active) {
            this.onFullscreenChange.emit(active);
        }

        if (this.fullscreenResizeTimer) clearTimeout(this.fullscreenResizeTimer);

        this.fullscreenResizeTimer = setTimeout(() => {
            this.fullscreenResizeTimer = null;
            window.dispatchEvent(new Event('resize'));
        }, 100);
    };

    private prevReported: { scale: number; rotation: number; flip: { x: number; y: number } } | null = null;

    onAfterViewChecked() {
        this.bindDirectiveInstance.setAttrs(this.ptms(['host', 'root']));
    }

    registerItem(existingIndex: number | null): number {
        if (existingIndex !== null) {
            if (existingIndex >= this.itemCounter) {
                this.itemCounter = existingIndex + 1;
            }

            return existingIndex;
        }

        const newIndex = this.itemCounter;

        this.itemCounter += 1;

        return newIndex;
    }

    handleNext() {
        if (this.itemCounter <= 0) return;

        const newIndex = (this.activeIndex() + 1) % this.itemCounter;

        this.activeIndex.set(newIndex);
        this.onActiveIndexChange.emit({ value: newIndex });
    }

    handlePrev() {
        if (this.itemCounter <= 0) return;

        const newIndex = (this.activeIndex() - 1 + this.itemCounter) % this.itemCounter;

        this.activeIndex.set(newIndex);
        this.onActiveIndexChange.emit({ value: newIndex });
    }

    selectItem(index: number) {
        if (index < 0 || index >= this.itemCounter) return;

        this.activeIndex.set(index);
        this.onActiveIndexChange.emit({ value: index });
    }

    dispatchAction(type: GalleryPendingAction['type']) {
        this.pendingAction.set({ type, timestamp: Date.now() });
    }

    clearPendingAction() {
        this.pendingAction.set(null);
    }

    constructor() {
        super();

        effect(() => {
            const fullscreenActive = this.fullscreen();

            if (fullscreenActive === undefined || isPlatformServer(this.platformId)) return;

            const el = this.$el as HTMLElement | null;

            if (!el || !this.document) return;

            const isNativeFullscreen = this.document.fullscreenElement === el;

            if (fullscreenActive && !isNativeFullscreen) {
                el.requestFullscreen?.()?.catch(() => {});
            } else if (!fullscreenActive && this.document.fullscreenElement) {
                this.document.exitFullscreen?.()?.catch(() => {});
            }
        });
    }

    onInit() {
        super.onInit();

        if (!isPlatformServer(this.platformId)) {
            this.document?.addEventListener('fullscreenchange', this.onNativeFullscreenChange);
        }
    }

    onDestroy() {
        this.destroyed = true;

        if (this.fullscreenResizeTimer) {
            clearTimeout(this.fullscreenResizeTimer);
            this.fullscreenResizeTimer = null;
        }

        this.document?.removeEventListener('fullscreenchange', this.onNativeFullscreenChange);

        if (this.document?.fullscreenElement === this.$el) {
            this.document.exitFullscreen?.().catch(() => {});
        }

        super.onDestroy();
    }

    handleKeyDown(event: KeyboardEvent) {
        if (event.key === 'ArrowRight') {
            event.preventDefault();
            this.handleNext();
        } else if (event.key === 'ArrowLeft') {
            event.preventDefault();
            this.handlePrev();
        } else if (event.key === 'Escape' && this.closeOnEscape() && this.isFullscreen()) {
            event.preventDefault();
            this.toggleFullScreen();
        }
    }

    toggleFullScreen() {
        if (this.fullscreen() !== undefined) {
            this.onFullscreenChange.emit(!this.fullscreen());

            return;
        }

        const el = this.$el as HTMLElement | null;

        if (!el || isPlatformServer(this.platformId)) return;

        if (this.document?.fullscreenElement) {
            this.document.exitFullscreen?.();
        } else {
            el.requestFullscreen?.();
        }
    }

    reportItemState(itemState: { zoomed: boolean; rotated: boolean; flipped: boolean; scale: number; rotation: number; flip: { x: number; y: number } }) {
        if (this.destroyed) return;

        this.activeItemTransform.set({ zoomed: itemState.zoomed, rotated: itemState.rotated, flipped: itemState.flipped });

        const prev = this.prevReported;

        if (!prev || prev.scale !== itemState.scale) this.onZoomChange.emit(itemState.scale);

        if (!prev || prev.rotation !== itemState.rotation) this.onRotateChange.emit(itemState.rotation);

        if (!prev || prev.flip.x !== itemState.flip.x || prev.flip.y !== itemState.flip.y) this.onFlipChange.emit(itemState.flip);

        this.prevReported = { scale: itemState.scale, rotation: itemState.rotation, flip: itemState.flip };
    }

    handleClickAction(action?: string) {
        if (!action) return;

        const actionMap: Record<string, () => void> = {
            zoomIn: () => this.dispatchAction('zoom-in'),
            zoomOut: () => this.dispatchAction('zoom-out'),
            rotateLeft: () => this.dispatchAction('rotate-left'),
            rotateRight: () => this.dispatchAction('rotate-right'),
            flipX: () => this.dispatchAction('flip-x'),
            flipY: () => this.dispatchAction('flip-y'),
            download: () => this.dispatchAction('download'),
            next: () => this.handleNext(),
            prev: () => this.handlePrev(),
            toggleFullScreen: () => this.toggleFullScreen()
        };

        actionMap[action]?.();
    }

    setContentEl(el: HTMLElement) {
        this.contentEl.set(el);
    }
}

@NgModule({
    imports: [
        Gallery,
        GalleryItem,
        GalleryHeader,
        GalleryContent,
        GalleryFooter,
        GalleryBackdrop,
        GalleryToolbar,
        GalleryToolbarItem,
        GalleryPrev,
        GalleryNext,
        GalleryZoomIn,
        GalleryZoomOut,
        GalleryZoomToggle,
        GalleryRotateLeft,
        GalleryRotateRight,
        GalleryFlipX,
        GalleryFlipY,
        GalleryFullScreen,
        GalleryDownload,
        GalleryThumbnail,
        GalleryThumbnailContent,
        GalleryThumbnailItem,
        SharedModule
    ],
    exports: [
        Gallery,
        GalleryItem,
        GalleryHeader,
        GalleryContent,
        GalleryFooter,
        GalleryBackdrop,
        GalleryToolbar,
        GalleryToolbarItem,
        GalleryPrev,
        GalleryNext,
        GalleryZoomIn,
        GalleryZoomOut,
        GalleryZoomToggle,
        GalleryRotateLeft,
        GalleryRotateRight,
        GalleryFlipX,
        GalleryFlipY,
        GalleryFullScreen,
        GalleryDownload,
        GalleryThumbnail,
        GalleryThumbnailContent,
        GalleryThumbnailItem,
        SharedModule
    ]
})
export class GalleryModule {}
